<section class="card"><h2>Structured screening</h2>
<?php if(empty($data['screening'])): ?><p>Structured screening not completed. <?= $app['source']==='email'?'Legacy email evidence is retained; no answers were inferred from documents.':'' ?></p>
<?php else: $s=$data['screening']; $labels=['pending'=>'Unscreened','minimum_met'=>'Minimum requirements met','minimum_not_met'=>'Minimum requirement not met','needs_review'=>'Needs review','preference'=>'Preference only']; ?><p><strong><?= e($labels[$s['outcome']]??$s['outcome']) ?></strong> · <?= $s['reviewed_at']?'Reviewed '.e($s['reviewed_at']).' UTC':'Awaiting HR review' ?></p><p>This is decision support. HR confirms all final workflow decisions.</p>
<?php foreach(json_decode($s['explanation']??'[]',true) as $answer): ?><article class="card"><h3><?= e($answer['label']) ?></h3><p>Required: <?= e((['gte'=>'At least','lte'=>'At most','eq'=>'Exactly','in'=>'One of','contains'=>'Includes all'][$answer['comparison']]??''). ' '.(is_array($answer['required'])?implode(', ',$answer['required']):(string)$answer['required'])) ?></p><p>Applicant answer: <?= e(is_array($answer['answer'])?json_encode($answer['answer'],JSON_UNESCAPED_UNICODE):(string)($answer['answer']??'Not provided')) ?></p><strong><?= e($labels[$answer['evaluation']]??$answer['evaluation']) ?></strong><p><?= e($answer['reason']) ?></p></article><?php endforeach; ?>
<?php if($can('edit')): ?><form method="post" action="<?= e($url('/save')) ?>"><?= $token() ?><input type="hidden" name="action" value="screening_review"><input type="hidden" name="id" value="<?= e($app['id']) ?>"><button class="btn">Confirm I reviewed these answers</button></form><?php endif; ?><?php endif; ?></section>
